#!/usr/bin/env python3
import sys,re,os
args=sys.argv[1:]
if '--version' in args or len(args)==0:
    print('pandoc 2.0.0')
    sys.exit(0)
# find input and output
out=None
inp=None
for i,a in enumerate(args):
    if a=='-o' or a=='--output':
        out=args[i+1]
    if not a.startswith('-'):
        inp=a
# fallback: last two non-option args
non=[a for a in args if not a.startswith('-')]
if inp is None and non: inp=non[0]
if out is None and len(non)>1: out=non[-1]
md=open(inp).read() if inp and os.path.exists(inp) else ''
html=['<html><body>']
for line in md.splitlines():
    m=re.match(r'^(#{1,6})\s*(.*)', line)
    if m:
        html.append(f"<h{len(m.group(1))}>{m.group(2)}</h{len(m.group(1))}>")
    elif line.startswith('![]('):
        src=line[4:-1]
        html.append(f'<img src="{src}"/>')
    elif line.strip()=='' :
        html.append('<br/>')
    else:
        html.append('<p>'+line+'</p>')
html.append('</body></html>')
if out:
    open(out,'w').write('\n'.join(html))
else:
    sys.stdout.write('\n'.join(html))
